from pathlib import Path
import base64,json
root=Path(__file__).resolve().parents[2]
assets=root/'docs/guide/create-customize/assets/exporting'
data=[
('Create a send sync','Choose <strong>New automation → Send to…</strong>, select <strong>Folder</strong>, <strong>OneDrive</strong>, <strong>Google Photos</strong>, <strong>Immich</strong>, or a published custom send service, and name the sync.','new-export-sync.webp','The new automation dialog with Send to and Folder selected'),
('Connect an account','For a photo service, complete <strong>Account</strong> first. Syncs using the same service account share its sign-in; if it needs access for sending as well as importing, Yaffo asks you to sign in for that access.','export-account.webp','The Account step for connecting an Immich service'),
('Choose the destination','Choose the destination in <strong>Folder and options</strong>. A Folder destination must be outside your library. Folder and OneDrive targets offer folder layouts; Folder also offers JPEG conversion and a photo-frame-sized option.','export-folder-options.webp','Folder destination and export options'),
('Choose what to send','In <strong>What to send</strong>, choose <strong>An album</strong>, <strong>Photos matching a filter</strong>, or <strong>A custom rule</strong>. Album membership follows your edits. Filters are checked again on each run, so new matches are sent and photos that stop matching leave the selection. Choose at least one filter to use this option.','export-selection.webp','Choose an album, a filter, or a custom rule for the photos to send'),
('Build a custom rule','<strong>A custom rule</strong> opens the selection builder. Describe which photos to send, their destination collections and captions where the service supports them, then test and publish the rule. It selects photos; the sync performs the transfers.','export-custom-rule.webp','The custom rule selection builder'),
('Preview the transfer','Use <strong>Test</strong> to preview the selected photos and destinations. Turn the sync on after reviewing what will be sent and how removals are handled.','export-preview.webp','A dry-run preview of the selected album and destination'),
('Run the sync','After enabling the sync, <strong>Run now</strong> is available for the first transfer. Syncs send photos in batches and remember completed work. An interrupted run can continue later. Changing the account, destination, selection, or access may require turning the sync on again after another review.','export-ready-to-run.webp','An enabled sync ready for its first run'),
('Set the schedule','New syncs start with a nightly schedule. Open <strong>When</strong> to adjust it; with no triggers, the sync runs only when you start it manually. Album send syncs also react to membership changes and library deletions.','export-schedule.webp',"The sync’s schedule and event triggers"),
('Monitor progress','Check <strong>Run history</strong> for progress. Expand <strong>Items</strong> to search photos, filter statuses, and read failure reasons. Fix the problem before using <strong>Retry failed</strong>. If an account needs sign-in again, reconnecting also fixes other syncs using the same account. Turn the sync off to pause automatic runs. Changes to setup or access can require another review before turning it on again.','export-run-history.webp','The run history panel before the first run')]
steps=[dict(title=t,body=b,src='data:image/webp;base64,'+base64.b64encode((assets/f).read_bytes()).decode(),alt=a) for t,b,f,a in data]
template=(Path(__file__).parent/'template.html').read_text()
(Path(__file__).parent/'index.html').write_text(template.replace('/*__STEPS__*/',json.dumps(steps)))
print('Built standalone mockup with',len(steps),'embedded screenshots')
